package com.voiceshift;
import android.app.*;import android.os.*;import android.media.*;import android.content.pm.PackageManager;import android.widget.*;import android.view.*;import android.graphics.*;
public class MainActivity extends Activity {
 volatile boolean running; volatile int pitch; volatile float robot,echo; volatile short[] waveform=new short[256]; Thread worker; Wave wave;
 public void onCreate(Bundle b){super.onCreate(b);LinearLayout l=new LinearLayout(this);l.setOrientation(1);l.setPadding(24,24,24,24);setContentView(l);TextView title=new TextView(this);title.setText("VoiceShift AI — use headphones");l.addView(title);wave=new Wave();l.addView(wave,new LinearLayout.LayoutParams(-1,240));Spinner s=new Spinner(this);String[] names={"Original","Male","Female","Deep","Robot","Alien","Cartoon","Demon"};s.setAdapter(new ArrayAdapter<String>(this,android.R.layout.simple_spinner_dropdown_item,names));l.addView(s);s.setOnItemSelectedListener(new android.widget.AdapterView.OnItemSelectedListener(){public void onNothingSelected(AdapterView<?> a){} public void onItemSelected(AdapterView<?> a,View v,int p,long id){pitch=new int[]{0,-4,5,-8,0,7,10,-10}[p];robot=new float[]{0,0,0,0,1,.6f,0,.4f}[p];echo=p==5?.2f:p==7?.3f:0;}});Button start=new Button(this);start.setText("Start microphone");l.addView(start);start.setOnClickListener(v->{if(checkSelfPermission(android.Manifest.permission.RECORD_AUDIO)!=PackageManager.PERMISSION_GRANTED)requestPermissions(new String[]{android.Manifest.permission.RECORD_AUDIO},1);else start();});Button stop=new Button(this);stop.setText("Stop");l.addView(stop);stop.setOnClickListener(v->running=false);}
 void start(){if(worker!=null&&worker.isAlive())return;running=true;worker=new Thread(()->{AudioRecord in=null;AudioTrack out=null;try{int rate=48000;int n=Math.max(2048,AudioRecord.getMinBufferSize(rate,16,2));in=new AudioRecord(MediaRecorder.AudioSource.VOICE_RECOGNITION,rate,16,2,n);out=new AudioTrack.Builder().setAudioAttributes(new AudioAttributes.Builder().setUsage(AudioAttributes.USAGE_MEDIA).build()).setAudioFormat(new AudioFormat.Builder().setSampleRate(rate).setEncoding(2).setChannelMask(4).build()).setBufferSizeInBytes(Math.max(n,AudioTrack.getMinBufferSize(rate,4,2))).setTransferMode(AudioTrack.MODE_STREAM).build();in.startRecording();out.play();short[] a=new short[256];float[] ring=new float[8192],delay=new float[8640];int w=0,e=0,t=0;double phase=0;while(running){int count=in.read(a,0,a.length);if(count<=0)break;for(int i=0;i<count;i++){float x=a[i]/32768f;ring[w]=x;phase=(phase+1025-Math.pow(2,pitch/12.0))%1024;double q=phase/1024;float y=pitch==0?x:(float)(tap(ring,w,32+phase)*Math.pow(Math.sin(Math.PI*q),2)+tap(ring,w,32+(phase+512)%1024)*Math.pow(Math.cos(Math.PI*q),2));w=(w+1)%ring.length;y*=1-robot+robot*Math.sin(2*Math.PI*65*t++/rate);float z=delay[e];delay[e]=y+z*.25f;e=(e+1)%delay.length;a[i]=(short)(32767*Math.max(-1,Math.min(1,y+echo*z)));}waveform=a.clone();wave.postInvalidate();out.write(a,0,count);}}catch(Exception ex){runOnUiThread(()->Toast.makeText(this,ex.toString(),Toast.LENGTH_LONG).show());}finally{running=false;if(in!=null)in.release();if(out!=null)out.release();}});worker.start();}
 static float tap(float[] b,int w,double d){double a=(w-d+b.length)%b.length;int i=(int)a;return (float)(b[i]*(1-a+i)+b[(i+1)%b.length]*(a-i));} protected void onStop(){running=false;super.onStop();}class Wave extends View{Paint p=new Paint();Wave(){super(MainActivity.this);}protected void onDraw(Canvas c){p.setColor(0xffa78bfa);p.setStrokeWidth(3);short[] a=waveform;for(int i=1;i<a.length;i++)c.drawLine((i-1)*getWidth()/(float)a.length,getHeight()*(.5f-a[i-1]/65536f),i*getWidth()/(float)a.length,getHeight()*(.5f-a[i]/65536f),p);}}
}
